export var getGraphikFamily = function getGraphikFamily(fontStackPrimary) {
  return fontStackPrimary.split(',').map(function (s) {
    return s.trim().replace(/['"]/g, '');
  }).find(function (f) {
    return f.includes('Graphik');
  }) || 'HPE Graphik';
};
